import java.util.*;

public class Main {
    static Map<String, List<String>> buildGraph() {
        Map<String, List<String>> graph = new LinkedHashMap<>();
        graph.put("user", Arrays.asList("dns"));
        graph.put("dns", Arrays.asList("lb"));
        graph.put("lb", Arrays.asList("app1", "app2"));
        graph.put("app1", Arrays.asList("cache", "db"));
        graph.put("app2", Arrays.asList("cache", "db"));
        graph.put("cache", Arrays.asList("db"));
        graph.put("db", new ArrayList<>());
        return graph;
    }

    static boolean canReach(Map<String, List<String>> graph, String start, String target, String removed) {
        if (start.equals(removed)) return false;
        Set<String> visited = new HashSet<>();
        Deque<String> queue = new ArrayDeque<>();
        queue.add(start);
        visited.add(start);
        while (!queue.isEmpty()) {
            String node = queue.poll();
            if (node.equals(target)) return true;
            for (String next : graph.getOrDefault(node, Collections.emptyList())) {
                if (!next.equals(removed) && !visited.contains(next)) {
                    visited.add(next);
                    queue.add(next);
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        Map<String, List<String>> graph = buildGraph();
        String[] componentsToCheck = {"dns", "lb", "app1", "app2", "cache", "db"};

        for (String component : componentsToCheck) {
            boolean stillReachable = canReach(graph, "user", "db", component);
            String verdict = stillReachable ? "NOT a SPOF, an alternate path still reaches the database" : "IS a SPOF, removing it disconnects the database entirely";
            System.out.println("Remove '" + component + "': " + verdict);
        }
    }
}

