def build_graph():
    return {
        "user": ["dns"],
        "dns": ["lb"],
        "lb": ["app1", "app2"],
        "app1": ["cache", "db"],
        "app2": ["cache", "db"],
        "cache": ["db"],
        "db": [],
    }


def can_reach(graph, start, target, removed):
    if start == removed:
        return False
    visited = {start}
    queue = [start]
    while queue:
        node = queue.pop(0)
        if node == target:
            return True
        for next_node in graph.get(node, []):
            if next_node != removed and next_node not in visited:
                visited.add(next_node)
                queue.append(next_node)
    return False


def main():
    graph = build_graph()
    components_to_check = ["dns", "lb", "app1", "app2", "cache", "db"]

    for component in components_to_check:
        still_reachable = can_reach(graph, "user", "db", component)
        verdict = "NOT a SPOF, an alternate path still reaches the database" if still_reachable else "IS a SPOF, removing it disconnects the database entirely"
        print(f"Remove '{component}': {verdict}")


if __name__ == "__main__":
    main()

