#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <queue>
using namespace std;

unordered_map<string, vector<string>> buildGraph() {
    unordered_map<string, vector<string>> graph;
    graph["user"] = {"dns"};
    graph["dns"] = {"lb"};
    graph["lb"] = {"app1", "app2"};
    graph["app1"] = {"cache", "db"};
    graph["app2"] = {"cache", "db"};
    graph["cache"] = {"db"};
    graph["db"] = {};
    return graph;
}

bool canReach(unordered_map<string, vector<string>>& graph, const string& start, const string& target, const string& removed) {
    if (start == removed) return false;
    unordered_set<string> visited;
    queue<string> q;
    q.push(start);
    visited.insert(start);
    while (!q.empty()) {
        string node = q.front();
        q.pop();
        if (node == target) return true;
        for (const string& next : graph[node]) {
            if (next != removed && visited.find(next) == visited.end()) {
                visited.insert(next);
                q.push(next);
            }
        }
    }
    return false;
}

int main() {
    auto graph = buildGraph();
    vector<string> componentsToCheck = {"dns", "lb", "app1", "app2", "cache", "db"};

    for (const string& component : componentsToCheck) {
        bool stillReachable = canReach(graph, "user", "db", component);
        string verdict = stillReachable ? "NOT a SPOF, an alternate path still reaches the database" : "IS a SPOF, removing it disconnects the database entirely";
        cout << "Remove '" << component << "': " << verdict << endl;
    }

    return 0;
}
